// Builds the synthetic session transcript (JSONL) that `claude --resume`
// replays. Every message is generated by the rig; no real transcript is read.

import { createHash } from "node:crypto";

/** Claude Code names a project folder after its cwd with every non-alphanumeric turned into "-". */
export function mangleCwd(cwd) {
  return cwd.replace(/[^A-Za-z0-9]/g, "-");
}

/** A UUID-shaped id derived from a seed string (stable across runs; an identifier, not a secret). */
export function derivedUuid(seed) {
  const h = createHash("sha256").update(seed).digest("hex");
  return [
    h.slice(0, 8),
    h.slice(8, 12),
    `4${h.slice(13, 16)}`,
    `${"89ab"[Number.parseInt(h[16], 16) % 4]}${h.slice(17, 20)}`,
    h.slice(20, 32),
  ].join("-");
}

function stamp(startMs, index) {
  return new Date(startMs + index * 5000).toISOString();
}

function base({ sessionId, cwd, version, parent, index, startMs, type }) {
  return {
    parentUuid: parent,
    isSidechain: false,
    userType: "external",
    cwd,
    sessionId,
    version,
    gitBranch: "",
    type,
    uuid: derivedUuid(`${sessionId}:${index}`),
    timestamp: stamp(startMs, index),
  };
}

function userRecord(ctx, text) {
  return {
    ...base({ ...ctx, type: "user" }),
    message: { role: "user", content: text },
  };
}

function assistantRecord(ctx, text) {
  return {
    ...base({ ...ctx, type: "assistant" }),
    message: {
      id: `msg_${String(ctx.index).padStart(24, "0")}`,
      type: "message",
      role: "assistant",
      model: "claude-sonnet-4-5-20250929",
      content: [{ type: "text", text }],
      stop_reason: "end_turn",
      stop_sequence: null,
      usage: {
        input_tokens: 10,
        output_tokens: 20,
        cache_creation_input_tokens: 0,
        cache_read_input_tokens: 0,
      },
    },
    requestId: `req_${String(ctx.index).padStart(24, "0")}`,
  };
}

/**
 * JSONL text of a session. `turns` is a list of {role: "user"|"assistant",
 * text}; records are chained by parentUuid in order.
 */
export function buildSession({ sessionId, cwd, version, startMs, turns }) {
  let parent = null;
  const lines = turns.map((turn, index) => {
    const ctx = { sessionId, cwd, version, parent, index, startMs };
    const make = turn.role === "user" ? userRecord : assistantRecord;
    const record = make(ctx, turn.text);
    parent = record.uuid;
    return JSON.stringify(record);
  });
  return `${lines.join("\n")}\n`;
}
